using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using StudentAccommodationSystem.Data; using StudentAccommodationSystem.Models;
namespace StudentAccommodationSystem.Controllers;
[Authorize] public class MaintenanceController(ApplicationDbContext db,UserManager<ApplicationUser> users):Controller
{ [Authorize(Roles="Student")] public async Task<IActionResult> Index(){var u=await users.GetUserAsync(User);var s=await db.StudentProfiles.FirstAsync(x=>x.UserId==u!.Id);return View(await db.MaintenanceRequests.Include(x=>x.Property).Include(x=>x.Room).Where(x=>x.StudentProfileId==s.Id).OrderByDescending(x=>x.CreatedAt).ToListAsync());}
 [Authorize(Roles="Student")] public async Task<IActionResult> Create(){var u=await users.GetUserAsync(User);var s=await db.StudentProfiles.FirstAsync(x=>x.UserId==u!.Id);ViewBag.Rooms=await db.RentalAgreements.Include(x=>x.Room).Where(x=>x.StudentProfileId==s.Id&&x.Status==AgreementStatus.Active).Select(x=>x.Room).ToListAsync();return View(new MaintenanceRequest());}
 [HttpPost,Authorize(Roles="Student"),ValidateAntiForgeryToken] public async Task<IActionResult> Create(MaintenanceRequest m){var u=await users.GetUserAsync(User);var s=await db.StudentProfiles.FirstAsync(x=>x.UserId==u!.Id);var room=await db.Rooms.FindAsync(m.RoomId);if(room==null)return NotFound();m.StudentProfileId=s.Id;m.PropertyId=room.PropertyId;db.MaintenanceRequests.Add(m);await db.SaveChangesAsync();return RedirectToAction(nameof(Index));}
 [Authorize(Roles="Owner,Administrator")] public async Task<IActionResult> Manage(){var q=db.MaintenanceRequests.Include(x=>x.Property).Include(x=>x.Room).AsQueryable();if(User.IsInRole("Owner")){var u=await users.GetUserAsync(User);var op=await db.OwnerProfiles.FirstAsync(x=>x.UserId==u!.Id);q=q.Where(x=>x.Property.OwnerProfileId==op.Id);}return View(await q.OrderByDescending(x=>x.CreatedAt).ToListAsync());}
 [HttpPost,Authorize(Roles="Owner,Administrator"),ValidateAntiForgeryToken] public async Task<IActionResult> UpdateStatus(int id,MaintenanceStatus status){var m=await db.MaintenanceRequests.FindAsync(id);if(m!=null){m.Status=status;await db.SaveChangesAsync();}return RedirectToAction(nameof(Manage));}}
